"/* RandomUsername.js
 *
 * Author: volker.scheuber@pingidentity.com
 *
 * Generate a random uuid as username and store it in shared state under 'username' and 'objectAttributes/userName'.
 *
 * Expected node outcomes:
 * - true: Random username successfully generated and stored in shared state.
 *
 * Scripted Decision node API: https://docs.pingidentity.com/pingoneaic/am-scripting/scripting-api-node.md
 * - Common Bindings: https://docs.pingidentity.com/pingoneaic/am-scripting/script-bindings.md
 * - Next Generation scripts: https://docs.pingidentity.com/pingoneaic/am-scripting/next-generation-scripts.md
 * Engine: Mozilla Rhino 1.7.14
 * ECMAScript support: Limited support for ES6 / ES2015 (often referred to as JavaScript version 1.7 in the docs). Full modern ES6+ features are not available.
 */
(function () {
    var SCRIPT_NAME = "RandomUsername";
    logger.error(`${SCRIPT_NAME}: Script started`);
    var username = String(utils.crypto.randomUUID());
    nodeState.putShared('username', "" + username);
    nodeState.mergeShared({ "objectAttributes": { "userName": "" + username } });
    logger.error(`${SCRIPT_NAME}: Generated random username: ${username}`);
    action.goTo('true');
    logger.error(`${SCRIPT_NAME}: Script finished`);
}());"

d96835dd-4bec-4ae5-8417-9f8eda25ba6c.script:
"/* SelectMerchant.js
 *
 * Author: volker.scheuber@pingidentity.com
 *
 * Obtain the merchant id from the merchant_id header, locate the merchant org (managed/alpha_organization)
 * by its merchantId attribute, and read its merchantTrustedIssuerConfig attribute. Merge that config with a
 * few hardcoded properties (transformationScript, scriptInputs, idTokenHeaderName) into a single nodeConfig
 * object matching the OIDC ID Token Validator node's configuration properties, and store it in shared state
 * under 'nodeConfig' for a downstream Config Provider node to imitate that node with.
 *
 * Expected node outcomes:
 * - true: Merchant ID successfully obtained and OIDC ID Token Validator node config generated in shared state.
 * - false: Failed to obtain a valid merchant ID, or no merchant org / merchantTrustedIssuerConfig was found for it.
 *
 * Scripted Decision node API: https://docs.pingidentity.com/pingoneaic/am-scripting/scripting-api-node.md
 * - Common Bindings: https://docs.pingidentity.com/pingoneaic/am-scripting/script-bindings.md
 * - Next Generation scripts: https://docs.pingidentity.com/pingoneaic/am-scripting/next-generation-scripts.md
 * Engine: Mozilla Rhino 1.7.14
 * ECMAScript support: Limited support for ES6 / ES2015 (often referred to as JavaScript version 1.7 in the docs). Full modern ES6+ features are not available.
 */
(function () {
  var SCRIPT_NAME = "SelectMerchant";
  var REALM = "alpha";

  // Config Provider node reads this via nodeState.get('nodeConfig').asMap()
  // to imitate the OIDC ID Token Validator node.
  var HARDCODED_NODE_CONFIG = {
    script: "892ec916-6027-40b4-8c5d-e750b66ce153",
    inputs: ["*","nodeConfig"],
    headerName: "merchant_token"
  };

  logger.error(`${SCRIPT_NAME}: Script started`);
  try {
    var merchantIdHeader = requestHeaders.get('merchant_id');
    var merchantId = merchantIdHeader && merchantIdHeader[0] ? String(merchantIdHeader[0]) : null;

    if (!merchantId || !/^[A-Za-z0-9_-]+$/.test(merchantId)) {
      logger.error(`${SCRIPT_NAME}: Missing or invalid merchant_id header: ${merchantId}`);
      action.goTo('false');
    }
    else {
      var queryParams = {
        _queryFilter: `merchantId eq '${merchantId}'`,
        _pageSize: 1
      };
      var results = openidm.query(`managed/${REALM}_organization`, queryParams, ['_id', 'merchantTrustedIssuerConfig']).result;
      logger.error(`${SCRIPT_NAME}: Merchant org lookup for '${merchantId}', number of results: ${results.length}`);

      var merchantTrustedIssuerConfig = results.length > 0 ? results[0].merchantTrustedIssuerConfig : null;

      if (!merchantTrustedIssuerConfig) {
        logger.error(`${SCRIPT_NAME}: No merchant org / merchantTrustedIssuerConfig found for merchantId: ${merchantId}`);
        action.goTo('false');
      }
      else {
        nodeState.mergeShared({ "objectAttributes": { "custom_merchantId": merchantId } });
        var nodeConfig = {};
        Object.keys(merchantTrustedIssuerConfig).forEach(function (key) {
          nodeConfig[key] = merchantTrustedIssuerConfig[key];
        });
        Object.keys(HARDCODED_NODE_CONFIG).forEach(function (key) {
          nodeConfig[key] = HARDCODED_NODE_CONFIG[key];
        });

        logger.error(`${SCRIPT_NAME}: Generated nodeConfig: ${JSON.stringify(nodeConfig)}`);
        nodeState.putShared('nodeConfig', nodeConfig);
        action.goTo('true');
      }
    }
  } catch (error) {
    logger.error(`${SCRIPT_NAME}: Error: ${error.message}\n${error.stack}`);
    nodeState.putShared('errorMessage', error.message);
    nodeState.putShared('errorStack', error.stack);
    action.goTo('false');
  }
  logger.error(`${SCRIPT_NAME}: Script finished`);
}());
"
